// ESLint 9 flat config for apps/vscode.
//
// R0.1.4 (2026-10-11) follow-up: the VS Code extension was the
// only app without an explicit lint script. This config mirrors
// the apps/{mcp,web}/ ones; future hardening can add
// `@typescript-eslint` and `no-console` for extension code.
//
// Ignores:
//   - out/   vsce build output
//   - *.vsix generated package
//   - *.d.ts generated by tsc

import js from '@eslint/js';

export default [
  {
    ignores: [
      'out/**',
      'dist/**',
      '*.vsix',
      '*.d.ts',
      'node_modules/**',
    ],
  },
  js.configs.recommended,
];